script:
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
"=== auth status ==="
opencode auth list 2>&1 | Select-Object -First 10
"=== config ==="
Get-Content "$env:USERPROFILE\.config\opencode\opencode.json" | ConvertFrom-Json | Select-Object model
"=== trying direct (short timeout) ==="
$job = Start-Job -ScriptBlock {
  $env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
  Set-Location "$env:USERPROFILE\Desktop\audit2"
  opencode run "hi" 2>&1 | Select-Object -First 5
}
if (Wait-Job $job -Timeout 30) {
  Receive-Job $job
} else {
  "TIMED OUT"
  Stop-Job $job
}
Remove-Job $job -Force
